    await vault.connect(alice).deposit(ALICE_DEPOSIT, aliceAddr);
    const aliceShares = await vault.balanceOf(aliceAddr);
    expect(aliceShares).to.equal(ALICE_DEPOSIT * SHARE_SCALE, "Alice must hold correct share amount");

